/* cppi::e5a246adf9134605ff4d9d99295cc56306de7fdcf9727a937a884d3a048bf98a */
SELECT run_date, outcome, ruleset_id, run_timestamp, run_id, lookback_days, rule_id, evaluation_message, rule, rule_description, rule_name, rule_type, ruleset_version, run_account_id, evaluated_metrics, rule_dimension, database_name, table_name, failed_record_count, failed_percent, file_process_date, raised_exception, total_records_tested, total_pass_count, total_pass_percentage, completion_time, recheck, job_type, group_name, owner_name, frequency, data_source, dataset, dq_source, evaluated_rule
FROM dataops.dq_results where table_name LIKE '%securities%' order by file_process_date  desc limit 10

/* cppi::dc39ab9eac1b8524033c7f9eaaec7b514ba6c058041457c25cacf93506082da7 */
SELECT COUNT(*) FROM (SELECT * FROM (
select business_date, cppib_sec_id AS cppib_id,  from_currency_code AS from_currency, 
to_currency_code AS to_currency, type AS instrument_type, sub_type AS instrument_sub_type,
bid_value, askvalue AS ask_value, mid_value AS mid_value, business_date AS rate_date,
price_source_code AS price_source from market_uat.cppib_rates
where business_date = date('2025-06-24') AND "type" = 'CURRENCY' AND sub_type = 'CROSS_RATE' AND price_source_code = 'WM Company'
) z_q WHERE from_currency IN ('CAD')
) dbvrcnt

